@layer components {
  :where([data-control-family="resizable"][data-slot="panel-group"]) {
    --resizable-group-background: var(--card);
    --resizable-group-radius: var(--radius-panel);
    --resizable-group-border-color: var(--border);
    --resizable-handle-color: var(--foreground);
    --resizable-handle-hover-background: oklch(from var(--foreground) l c h / 0.25);
    --resizable-handle-active-background: oklch(from var(--foreground) l c h / 0.4);
    --resizable-grip-radius: var(--radius-control);
    --resizable-grip-background: var(--card);
    --resizable-grip-foreground: var(--muted-foreground);
    background-color: var(--resizable-group-background);
    color: var(--card-foreground);
  }

  :where([data-control-family="resizable"][data-slot="panel-group"][data-variant="framed"]) {
    border: 1px solid var(--resizable-group-border-color);
    border-radius: var(--resizable-group-radius);
    box-shadow: var(--shadow-sm);
  }

  :where([data-control-family="resizable"][data-slot="handle"]) {
    --_resizable-gradient-color: var(--resizable-handle-color);
    transition-property: background-color, box-shadow, opacity;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-standard);
  }

  :where([data-control-family="resizable"][data-slot="handle"][data-variant="solid"]) {
    background-color: var(--border);
  }

  :where(
    [data-control-family="resizable"][data-slot="handle"][data-variant="solid"][data-separator="hover"],
    [data-control-family="resizable"][data-slot="handle"][data-variant="solid"][data-separator="focus"]
  ) {
    background-color: var(--resizable-handle-hover-background);
  }

  :where([data-control-family="resizable"][data-slot="handle"][data-variant="solid"][data-separator="active"]) {
    background-color: var(--resizable-handle-active-background);
  }

  :where([data-control-family="resizable"][data-slot="handle"][data-separator="focus"]) {
    box-shadow: 0 0 0 2px oklch(from var(--foreground) l c h / 0.2);
  }

  :where([data-control-family="resizable"][data-slot="handle"][data-separator="disabled"]) {
    opacity: 0.5;
  }

  :where([data-control-family="resizable"][data-slot="handle"][data-variant="hover"])::before {
    position: absolute;
    inset: 0;
    content: "";
    opacity: 0;
    transition-property: opacity;
    transition-duration: var(--duration-base);
    transition-timing-function: var(--ease-standard);
  }

  :where([data-control-family="resizable"][data-slot="handle"][data-variant="hover"][data-axis="vertical"])::before {
    background-image: linear-gradient(
      to bottom,
      var(--_resizable-gradient-color),
      oklch(from var(--_resizable-gradient-color) l c h / 0)
    );
  }

  :where([data-control-family="resizable"][data-slot="handle"][data-variant="hover"][data-axis="horizontal"])::before {
    background-image: linear-gradient(
      to right,
      var(--_resizable-gradient-color),
      oklch(from var(--_resizable-gradient-color) l c h / 0)
    );
  }

  :where(
    [data-control-family="resizable"][data-slot="handle"][data-variant="hover"]:is(
      [data-separator="hover"],
      [data-separator="focus"],
      [data-separator="active"]
    )
  )::before {
    opacity: 1;
  }

  :where([data-control-family="resizable"][data-slot="handle-grip"]) {
    border: 1px solid var(--border);
    border-radius: var(--resizable-grip-radius);
    background-color: var(--resizable-grip-background);
    color: var(--resizable-grip-foreground);
    box-shadow: var(--shadow-sm);
    opacity: 1;
    transition-property: opacity;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-standard);
  }

  :where([data-control-family="resizable"][data-slot="handle-grip"][data-variant="hover"]) {
    opacity: 0;
  }

  :where(
    [data-control-family="resizable"][data-slot="handle"]:is(
      [data-separator="hover"],
      [data-separator="focus"],
      [data-separator="active"]
    ) > [data-slot="handle-grip"][data-variant="hover"]
  ) {
    opacity: 1;
  }

  :where([data-control-family="resizable"][data-slot="handle"]) {
    --_resizable-handle-outline: none;
    outline-style: var(--_resizable-handle-outline);
  }
}

@property --resizable-group-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --resizable-group-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --resizable-group-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --resizable-handle-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --resizable-handle-hover-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --resizable-handle-active-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --resizable-grip-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --resizable-grip-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

